Item.method_code:
const { selectedId, tocData } = options.getState();
const selectedRelshipItem = tocData.get(selectedId);
const selectedButton = tocData.get(selectedRelshipItem?.related_id);
if (selectedButton?.name === 'com.aras.innovator.cui_default.toc_editor') {
	const notify = aras.getNotifyByContext(window);
	const errorMessage = aras.getResource('', 'toc_editor.delete_toc_editor');
	notify(errorMessage, { type: 'error' });

	return;
}

const { deleteItem } = options.getActions();

deleteItem(selectedId);
